import{c as t,Q as o,j as r,m as s}from"./chunks/framework.BXc4yaFE.js";const k=JSON.parse('{"title":"Markdown Is A Context Interface","description":"","frontmatter":{"url":"https://x.com/dongxi_nlp/status/2066290950352081336","title":"Markdown Is A Context Interface","author":"马东锡 NLP","archived":"2026-06-16T00:00:00.000Z","handle":"@dongxi_nlp","published":"2026-06-14T00:00:00.000Z","stats":"94 likes · 22 retweets · 206 bookmarks · 84482 views","tags":["harness","markdown","context-management","agents-md","skill-md","coding-agent"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-14-@dongxi_nlp-081336.md","filePath":"research/tweets/2026-06-14-@dongxi_nlp-081336.md","lastUpdated":1785909234000}'),a={name:"research/tweets/2026-06-14-@dongxi_nlp-081336.md"};function n(l,e,i,d,c,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="markdown-is-a-context-interface-—-dongxi-nlp" tabindex="-1">Markdown Is A Context Interface — @dongxi_nlp <a class="header-anchor" href="#markdown-is-a-context-interface-—-dongxi-nlp" aria-label="Permalink to &quot;Markdown Is A Context Interface — @dongxi_nlp&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/dongxi_nlp/status/2066290950352081336" target="_blank" rel="noreferrer">https://x.com/dongxi_nlp/status/2066290950352081336</a><strong>作者</strong>：马东锡 NLP（@dongxi_nlp） <strong>發布日期</strong>：2026-06-14 <strong>收錄日期</strong>：2026-06-16 <strong>類型</strong>：Twitter Article（Harness 系列第 5 篇） <strong>統計</strong>：94 likes · 22 retweets · 206 bookmarks · 84482 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Harness 系列文章之 5，小小的 markdown 文件，却可以改变 Coding Agent 的世界状态。</p><blockquote><p>.md file works when the harness knows what kind of context it is. [圖 1] 现代 coding agent 里，一个很有意思的现象是：普通 markdown 文件可以改变 agent behavior。 加一个 AGENTS.md，Agent 开始遵守 repo-specific rules。 加一个 SKILL.md，Agent 在某类 task 上突然更稳定。 Markdown file 只是可见部分。 真正有趣的是 Harness 对这种机制的设计： [圖 2]</p></blockquote><h2 id="the-naive-markdown-dump" tabindex="-1">The Naive Markdown Dump <a class="header-anchor" href="#the-naive-markdown-dump" aria-label="Permalink to &quot;The Naive Markdown Dump&quot;">​</a></h2><p>按照习惯，如果我们从一个从 tiny agent 看 markdown： [圖 3] 这看起来合理，因为 rules，docs，plans，procedures 都经常写在 markdown 里。 但 raw markdown dumping 有代价：</p><ul><li>旧 notes 会和当前 instructions 竞争</li><li>长 docs 会挤掉最近的 tool result</li><li>drafts 可能被误当成 rules</li><li>general project guidance 可能盖过 narrow task procedure Model 得到了更多 text，但 task 得到的有用的 instruction 更少。 所以，</li></ul><blockquote><p>.md 应该通过 Harness route 进入 context，不能直接倒进 prompt。</p></blockquote><h2 id="two-files-two-jobs" tabindex="-1">Two Files, Two Jobs <a class="header-anchor" href="#two-files-two-jobs" aria-label="Permalink to &quot;Two Files, Two Jobs&quot;">​</a></h2><p>这里，我们可以一起看两个常用 markdown files，AGENTS.md 以及 SKILLS.md [圖 4] 它们都是 markdown, 但进入 prompt 的方式不一样。</p><blockquote><p>AGENTS.md ：In this workspace, behave like this. SKILL.md ：For this kind of task, use this procedure.</p></blockquote><h2 id="why-agents-md-works" tabindex="-1">Why AGENTS.md Works <a class="header-anchor" href="#why-agents-md-works" aria-label="Permalink to &quot;Why AGENTS.md Works&quot;">​</a></h2><p>AGENTS.md 有效，是因为 Harness 把它当成 workspace instruction context。 它是 project guidance，应该在 model 开始操作 repo 前可见。 例如我自己的 Dongxi Agent 主要任务是要根据每天与 coding agent的交互中，总结学习经验。 那么，在 DongXi 这个 workspace 里，AGENTS.md 要求：做 DongXi Agent 或 coding-agent harness learning 时，要保持 learning artifact current。 这一个文件会改变整个 session 的行为： [圖 5] Model 仍然负责 writing 和 reasoning。 但 Harness 在 turn 开始前插入了稳定的 project rule。 这就是 AGENTS.md 强的地方：</p><ul><li>它从 workspace 被发现</li><li>它被 project 或 directory scope 限定</li><li>它进入 stable instruction layer</li><li>它跨多个 tasks 持续生效</li><li>它让用户不必在每个 prompt 里重复 local conventions</li></ul><h2 id="how-agents-md-works" tabindex="-1">How AGENTS.md Works <a class="header-anchor" href="#how-agents-md-works" aria-label="Permalink to &quot;How AGENTS.md Works&quot;">​</a></h2><p>[圖 6]</p><ul><li>Harness 应该知道每条 rule 适用于哪个 directory。</li><li>nested workspace 可能有更窄的 rules。</li><li>这些 rules 应该被当成 instruction context，同时仍然低于 system 和 developer policy。</li><li>文件内容不应该被盲目复制进每条 visible transcript message。</li><li>它属于 stable context layer。 这样 prompt 可以保持一致，又不会把 project rules 变成 noisy chat history。</li></ul><h2 id="where-agents-md-enters-the-agent-turn" tabindex="-1">Where Agents.md Enters The Agent Turn <a class="header-anchor" href="#where-agents-md-enters-the-agent-turn" aria-label="Permalink to &quot;Where Agents.md Enters The Agent Turn&quot;">​</a></h2><p>[圖 7] AGENTS.md 在 model turn 组装前加载。 它进入 stable workspace instruction context，和 project rules、local operating constraints 放在一起。transcript 记录发生了什么；AGENTS.md 约束接下来该怎么做。</p><h2 id="why-skill-md-works" tabindex="-1">Why SKILL.md Works <a class="header-anchor" href="#why-skill-md-works" aria-label="Permalink to &quot;Why SKILL.md Works&quot;">​</a></h2><p>SKILL.md 有效，原因不同。 它能提升某类 task 的表现，是因为它在正确时机给 model 一个聚焦的 procedure。 没有 skill 时，model 可能懂一般领域，但会漏掉 local workflow。 有 skill 时，Harness 可以提供：</p><ul><li>什么时候使用这个 workflow</li><li>哪些 files 或 artifacts 重要</li><li>哪些 tools 被允许或期待使用</li><li>应该按什么步骤做</li><li>什么 checks 证明工作完成</li><li>用户期待什么 output format 这比一句 vague prompt 强得多： [圖 8] 这个文件会提升 performance，因为它把 fuzzy ability 变成 repeatable procedure。</li></ul><h2 id="how-skill-md-works" tabindex="-1">How SKILL.md Works <a class="header-anchor" href="#how-skill-md-works" aria-label="Permalink to &quot;How SKILL.md Works&quot;">​</a></h2><p>好的 Harness 不会把所有 skills 都塞进 default prompt。 它使用 progressive disclosure。 在 startup 或 capability refresh 时，Harness 扫描 skill folders： [圖 9] Model 可以看到这个 skill 存在。 用户也可以通过 /skills 之类的 local command 看到它。 完整 body 在 task 需要时才进入 context。</p><h2 id="where-skills-md-enters-the-agent-turn" tabindex="-1">Where Skills.md Enters The Agent Turn <a class="header-anchor" href="#where-skills-md-enters-the-agent-turn" aria-label="Permalink to &quot;Where Skills.md Enters The Agent Turn&quot;">​</a></h2><p>[圖 10] SKILL.md 先以 capability metadata 出现，task invoke 之后才加载 body。 它进入 task procedure context：steps、tool expectations、checks、output shape。这个 context 只服务当前 workflow，不扩散成 always-on workspace policy。</p><p>小小的 markdown，没有改变 model weights。 却改变了该 task 里的 harness-managed context、tools 和 workflow。 合适使用这些 markdown，是 coding agent 最关心的问题。 而：</p><blockquote><p>在恰当的时机，把不同的 markdown 文件加载进context，就是 harness 应该做的事情。</p></blockquote><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Markdown 文件不應直接倒入 prompt，應透過 Harness 依類型路由——AGENTS.md 是 workspace-scoped 持久政策，SKILL.md 是按需加載的任務程序，progressive disclosure 防止 context 污染。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Raw markdown dump 的代價</strong>：直接倒入 prompt 讓舊 notes 與當前 instructions 競爭、長 docs 擠掉最近工具輸出、drafts 被誤當 rules，model 文字更多但有用指令更少</li><li><strong>Two Files, Two Jobs</strong>：AGENTS.md = workspace-scoped system instruction（「In this workspace, behave like this」）；SKILL.md = task procedure（「For this kind of task, use this procedure」）</li><li><strong>AGENTS.md 的機制</strong>：Harness 當 workspace-scoped system instruction 插入，model 把它當持久約定而非可選建議，覆蓋範圍是整個工作空間</li><li><strong>SKILL.md 的 progressive disclosure</strong>：啟動時只加載 capability metadata，task invoke 後才加載完整 body（steps、tool expectations、checks、output shape），只服務當前 workflow，不擴散為 always-on policy</li><li><strong>Harness 的核心職責</strong>：在恰當時機把不同類型的 markdown 加載進 context，而非靜態地把所有 markdown 塞入 prompt</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><strong>AGENTS.md</strong>：workspace policy（workspace-scoped persistent system instruction）</li><li><strong>SKILL.md</strong>：task procedure（steps、tool expectations、checks、output shape）</li><li><strong>Progressive disclosure</strong>：startup 掃描 skill folders 顯示 capability metadata，task invoke 時才加載 full body</li><li><strong><code>/skills</code> local command</strong>：供用戶查看可用 skill 列表</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>直接對應 cc-workspace 現有設計</strong>：CLAUDE.md 是 workspace policy，<code>.claude/skills/</code> 是 task procedure，本文的框架可做互相驗證，並強化 progressive disclosure 的正確性</li><li><strong>Progressive disclosure 的實作細節省略</strong>：文章提供清晰 mental model，但未說明具體技術實作（掃描時機、metadata schema、context window 計算）</li><li><strong>多 SKILL 交叉情境未討論</strong>：當 task 橫跨多個 SKILL 時的 route 策略，是 harness 設計的邊界情況，未作說明</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>直接對應 cc-workspace 的 CLAUDE.md/skills/ 設計，可強化 skill metadata 設計原則</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>&quot;Context Interface&quot; 詮釋有洞見；Two Files Two Jobs 框架清晰易用</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>概念分析為主，圖示不可見（僅佔位符），無量化數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>Progressive disclosure 機制、workspace vs task context 分離有技術深度</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>適用所有 coding agent harness 設計，AGENTS.md/SKILL.md 模式跨框架通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.7/10</strong></td><td>9×0.3+7×0.2+6×0.2+7×0.15+9×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Markdown-as-context-interface 與 progressive disclosure 是 harness context management 的通用原則，直接強化 cc-workspace 的 CLAUDE.md/skills/ 架構設計。</p>',43)])])}const m=t(a,[["render",n]]);export{k as __pageData,m as default};
